add_action( 'init', 'perfectpixel_move_upsells_setup' );
add_filter( 'woocommerce_upsell_display_args', 'perfectpixel_move_upsells_args' );
add_filter( 'woocommerce_loop_add_to_cart_link', 'perfectpixel_move_upsells_buttons', 50 );

function perfectpixel_move_upsells_setup() {
	remove_action( 'woocommerce_after_single_product_summary', 'woocommerce_upsell_display', 15 );
	add_action( 'woocommerce_single_product_summary', 'woocommerce_upsell_display', 35 );
}

function perfectpixel_move_upsells_args( $args ) {
	$args['columns']        = max( 1, (int) '{{upsells_columns}}' );
	$args['posts_per_page'] = max( 1, (int) '{{upsells_limit}}' );
	return $args;
}

function perfectpixel_move_upsells_buttons( $html ) {
	return ( 'yes' === '{{upsells_hide_buttons}}' && 'up-sells' === wc_get_loop_prop( 'name' ) ) ? '' : $html;
}
